// Show the syllabus code, subject strand and how many note sections this topic has.
const topicId = globalContext.pageParameters['topicId'];
const topics = globalContext.tableViews['2e7e24ea-7339-4bca-954a-24f38b47379d']?.data || [];
const notes = globalContext.tableViews['7d4719cb-9d6a-48ce-9a85-4bf524fabe90']?.data || [];
const topic = topics.find(function (t) { return t?.id === topicId; });
if (!topic) return 'Choose a topic from the Notes page to start reading.';
const sectionCount = notes.filter(function (n) { return n?.topic_id === topicId; }).length;
const parts = [];
if (topic.code) parts.push(String(topic.code).toUpperCase());
if (topic.category) parts.push(topic.category);
parts.push(sectionCount + (sectionCount === 1 ? ' note section' : ' note sections'));
return parts.join(' · ');

// Count how many of this topic's note sections the student has marked reviewed.
const topicId = globalContext.pageParameters['topicId'];
const notes = globalContext.tableViews['7d4719cb-9d6a-48ce-9a85-4bf524fabe90']?.data || [];
