const ownNotes = notes.filter(function (n) { return n?.topic_id === topicId; });
if (!ownNotes.length) return 'No sections yet';
const doneCount = ownNotes.filter(function (n) { return reviewed[n.id]; }).length;
return doneCount + '/' + ownNotes.length + ' note sections reviewed';

// Reflect whether this particular section has been marked reviewed.
