// Flip the reviewed flag for the note section whose button was clicked.
const reviewed = variables['439e3f7b-f911-4841-9ef0-612168ab6596'] || {};
const noteId = context.item.data?.id;
if (!noteId) return reviewed;

// Copy the map so we never mutate the variable in place.
const updated = Object.assign({}, reviewed);

if (updated[noteId]) {
  // Already reviewed, so this click means undo.
  delete updated[noteId];
} else {
  updated[noteId] = true;
}

return updated;

