// Collect unique activity days from stored dates + attempt timestamps + today
const attempts = globalContext.tableViews['daa3142c-6fa2-4985-acb7-2ac36dcfc0a4']?.data || [];
const stored = variables['4e008278-4a17-4bbe-9aa7-a0166af8dcce'] || [];
const dateSet = {};
for (let i = 0; i < stored.length; i++) {
  if (stored[i]) dateSet[stored[i]] = true;
}
for (let j = 0; j < attempts.length; j++) {
  const raw = attempts[j]?.createdAt || attempts[j]?.created_at;
  if (raw) dateSet[String(raw).slice(0, 10)] = true;
}
const now = new Date();
const today = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-' + String(now.getDate()).padStart(2, '0');
dateSet[today] = true;
return Object.keys(dateSet).sort();

// Count consecutive days ending today or yesterday
const dates = variables['4e008278-4a17-4bbe-9aa7-a0166af8dcce'] || [];
const dateSet = {};
for (let i = 0; i < dates.length; i++) dateSet[dates[i]] = true;
const now = new Date();
const pad = function(n) { return String(n).padStart(2, '0'); };
const toKey = function(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); };
const today = toKey(now);
const yesterdayDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
const yesterday = toKey(yesterdayDate);
let cursor;
if (dateSet[today]) cursor = new Date(now.getFullYear(), now.getMonth(), now.getDate());
else if (dateSet[yesterday]) cursor = yesterdayDate;
else return 0;
let streak = 0;
while (dateSet[toKey(cursor)]) {
  streak++;
  cursor = new Date(cursor.getFullYear(), cursor.getMonth(), cursor.getDate() - 1);
}
return streak;
